-- GCMB dev seed for PostgreSQL / pgAdmin 4, generated from the September 2026 workbook.
-- Run ONLY while connected to database gcmb_excel_2026 on the isolated PostgreSQL server (127.0.0.1:5433).
-- The old gcmb database and its append-only history are never modified.
-- Marker: TST-GCMB-EXCEL-2026. All individual bookings, room allocations, payments and expenses are GIẢ LẬP.
-- September aggregates for nine confirmed branches are from Excel; Tan Binh and other months are GIẢ LẬP.
-- Excel refunds are kept as reference amounts, not inserted as OPEX: GCMB operating profit differs by refunds.
-- Excel deposit usage, cash/bank mix, hotel service mix and F&B detail cannot be reconstructed from aggregates.
-- Settlement is modelled as GIẢ LẬP cash bills. No deposit, refund or F&B source record is invented.
-- Confirmed by user: Excel 'Cinema Hồ Tây' maps to HO_TAY; 'Hotel Hoàng Công Chất' maps to HN_HOANG_CONG_CHAT.
-- September workbook revenue is zero on 21-30/09 for the nine mapped branches; this script preserves that pattern.
-- Money: round monthly Excel totals HALF_UP to whole VND, then allocate remainder to daily rows.
BEGIN;
SET LOCAL TIME ZONE 'Asia/Ho_Chi_Minh';
CREATE TEMP TABLE _seed_month (branch_code text, month date, revenue bigint, variable_cost bigint,
 salary bigint, fixed_other bigint, refund_reference bigint, source_label text) ON COMMIT DROP;
