DO $seed$
DECLARE
  tag constant text := 'TST-GCMB-EXCEL-2026';
  m record; d record; br record; employee_row record;
  accountant uuid; head_office uuid; receptionist_role uuid; central_account uuid;
  actor_id uuid; branch_id uuid; account_id uuid; period_id uuid; payroll_period_id uuid;
  expense_id uuid; expense_payment_id uuid;
  payroll_entry_id uuid; salary_payment_id uuid; transaction_id uuid;
  i integer; salary_amount bigint; paid_at timestamptz;
BEGIN
  IF current_database() <> 'gcmb_excel_2026' THEN
    RAISE EXCEPTION 'Wrong database: expected gcmb_excel_2026, got %', current_database();
  END IF;
  IF (SELECT count(*) FROM public.flyway_schema_history WHERE success) <> 59
     OR NOT EXISTS (SELECT 1 FROM public.flyway_schema_history WHERE version='59' AND success) THEN
    RAISE EXCEPTION 'Flyway V1-V59 must be installed';
  END IF;
  IF (SELECT count(*) FROM gcmb.branch b JOIN (SELECT DISTINCT branch_code FROM _seed_month) s ON s.branch_code=b.code WHERE b.status='ACTIVE') <> 10
     OR EXISTS (SELECT 1 FROM _seed_month s JOIN gcmb.branch b ON b.code=s.branch_code
                WHERE (SELECT count(*) FROM gcmb.room r WHERE r.branch_id=b.id AND r.operating_status='AVAILABLE') < 6) THEN
    RAISE EXCEPTION 'Ten active branches with six available rooms each are required';
  END IF;
  IF EXISTS (SELECT 1 FROM gcmb.booking WHERE code LIKE 'TST-GCMB-20261114%')
     OR EXISTS (SELECT 1 FROM gcmb.payment WHERE idempotency_key LIKE 'TST-GCMB-20261114%')
     OR EXISTS (SELECT 1 FROM gcmb.price_rule WHERE code LIKE 'TST-GCMB-20261114%') THEN
    RAISE EXCEPTION 'Old test data is present; use a clean database';
  END IF;
  IF EXISTS (SELECT 1 FROM gcmb.booking WHERE code LIKE tag||'%') THEN
    IF (SELECT count(*) FROM gcmb.booking WHERE code LIKE tag||'%') <>
       (SELECT sum(least(12,greatest(1,(revenue/300000)::integer))) FROM _seed_day WHERE revenue>0)
       OR (SELECT count(*) FROM gcmb.bill WHERE number LIKE tag||'%') <>
       (SELECT count(*) FROM gcmb.booking WHERE code LIKE tag||'%') THEN
      RAISE EXCEPTION 'Incomplete prior seed; do not append to immutable history';
    END IF;
    RETURN; -- A complete seed is intentionally a no-op on rerun.
  END IF;
  IF EXISTS (SELECT 1 FROM gcmb.expense WHERE code LIKE tag||'%')
     OR EXISTS (SELECT 1 FROM gcmb.price_rule WHERE code LIKE tag||'%')
     OR EXISTS (SELECT 1 FROM gcmb.employee WHERE code LIKE tag||'%') THEN
    RAISE EXCEPTION 'Partial seed marker exists without bookings';
  END IF;
  IF EXISTS (SELECT 1 FROM gcmb.booking b JOIN gcmb.branch br ON br.id=b.branch_id
             WHERE br.code IN (SELECT DISTINCT branch_code FROM _seed_month)) THEN
    RAISE EXCEPTION 'Target branches already contain bookings outside this seed';
  END IF;
  SELECT id INTO accountant FROM gcmb.user_account WHERE username='ketoan' AND status='ACTIVE';
  SELECT id INTO head_office FROM gcmb.user_account WHERE username='qlcc' AND status='ACTIVE';
  SELECT id INTO receptionist_role FROM gcmb.role WHERE code='RECEPTIONIST';
  SELECT id INTO central_account FROM gcmb.financial_account WHERE code='PAYROLL-CENTRAL' AND active;
  IF accountant IS NULL OR head_office IS NULL OR receptionist_role IS NULL OR central_account IS NULL THEN
    RAISE EXCEPTION 'Missing accountant, head office manager, receptionist role or central financial account';
  END IF;
  INSERT INTO gcmb.financial_period(month,status)
  SELECT month,'OPEN' FROM (SELECT DISTINCT month FROM _seed_month) x ORDER BY month;
  INSERT INTO gcmb.payroll_period(month,status,confirmed_by,confirmed_at)
  SELECT month,'CONFIRMED',accountant,(month+interval '14 days') AT TIME ZONE 'Asia/Ho_Chi_Minh'
  FROM (SELECT DISTINCT month FROM _seed_month) x ORDER BY month;
  INSERT INTO gcmb.expense_category(code,name,class,active) VALUES
    (tag||'-FIXED','Chi phí cố định tổng hợp GIẢ LẬP','OPEX',true),
    (tag||'-VARIABLE','Chi phí biến đổi tổng hợp GIẢ LẬP','OPEX',true);
  INSERT INTO gcmb.price_rule(room_type_id,branch_id,name,valid_from,valid_to,day_kind,
    minute_from,minute_to,hourly_price,overtime_hourly_price,billing_step_minutes,priority,active,code,version,weekdays)
  SELECT rt.id,NULL,'Giá lịch sử GIẢ LẬP 2026','2026-01-01','2026-11-17','ALL',0,1440,
    CASE rt.code WHEN 'RT-QN' THEN 96000 WHEN 'RT-KG' THEN 106000 ELSE 110000 END,
    120000,60,1,false,tag||'-PR-'||rt.code,1,ARRAY[1,2,3,4,5,6,7]::smallint[]
  FROM gcmb.room_type rt WHERE rt.code IN ('RT-QN','RT-KG','RT-MUSIC');
  FOR br IN SELECT id,code FROM gcmb.branch WHERE code IN (SELECT DISTINCT branch_code FROM _seed_month) ORDER BY code LOOP
    INSERT INTO gcmb.user_account(username,email,password_hash,role_id,status,failed_login_count,branch_id)
    VALUES (lower(replace(tag,'-','_')||'_'||br.code),lower(replace(tag,'-','_')||'_'||br.code)||'@example.invalid',
      '!disabled-test-account',receptionist_role,'REVOKED',0,br.id) RETURNING id INTO actor_id;
    FOR i IN 1..4 LOOP
      INSERT INTO gcmb.employee(code,full_name,hired_on,status)
      VALUES (tag||'-EMP-'||br.code||'-'||i,'Nhân viên GIẢ LẬP '||br.code||' '||i,'2026-01-01','ACTIVE');
      INSERT INTO gcmb.employee_assignment(employee_id,branch_id,valid_from,is_branch_manager,assigned_by,reason)
      SELECT id,br.id,'2026-01-01'::date AT TIME ZONE 'Asia/Ho_Chi_Minh',false,accountant,tag||' GIẢ LẬP'
      FROM gcmb.employee WHERE code=tag||'-EMP-'||br.code||'-'||i;
    END LOOP;
  END LOOP;
  FOR m IN SELECT * FROM _seed_month ORDER BY month,branch_code LOOP
    SELECT id INTO branch_id FROM gcmb.branch WHERE code=m.branch_code;
    SELECT id INTO actor_id FROM gcmb.user_account WHERE username=lower(replace(tag,'-','_')||'_'||m.branch_code);
    SELECT id INTO period_id FROM gcmb.financial_period WHERE month=m.month;
    SELECT id INTO payroll_period_id FROM gcmb.payroll_period WHERE month=m.month;
    SELECT a.id INTO account_id FROM gcmb.financial_account a WHERE a.branch_id=branch_id AND a.kind='CASH_DRAWER' AND a.active LIMIT 1;
    IF account_id IS NULL THEN RAISE EXCEPTION 'Missing cash drawer for %',m.branch_code; END IF;
    paid_at := (m.month+interval '14 days 16 hours') AT TIME ZONE 'Asia/Ho_Chi_Minh';
    -- BR-103/104/107: fixed operating costs and payroll enter the operating result separately.
    FOR employee_row IN SELECT id,code FROM gcmb.employee WHERE code LIKE tag||'-EMP-'||m.branch_code||'-%' ORDER BY code LOOP
      i := split_part(employee_row.code,'-',array_length(string_to_array(employee_row.code,'-'),1))::integer;
      salary_amount := m.salary / 4 + CASE WHEN i <= m.salary % 4 THEN 1 ELSE 0 END;
      INSERT INTO gcmb.payroll_entry(period_id,employee_id,gross_amount,deduction_amount,net_amount)
      VALUES (payroll_period_id,employee_row.id,salary_amount,0,salary_amount) RETURNING id INTO payroll_entry_id;
      INSERT INTO gcmb.payroll_component(payroll_entry_id,branch_id,kind,minutes,hourly_rate_snapshot,multiplier,amount,calculation_snapshot,reason)
      VALUES (payroll_entry_id,branch_id,'ADDITION',0,0,1,salary_amount,
        jsonb_build_object('source',m.source_label,'marker',tag),tag||' GIẢ LẬP từ tổng lương tháng');
      INSERT INTO gcmb.salary_payment(payroll_entry_id,amount,status,paid_at,processed_by,idempotency_key)
      VALUES (payroll_entry_id,salary_amount,'PAID',paid_at,accountant,tag||'-SAL-'||m.branch_code||'-'||to_char(m.month,'YYYYMM')||'-'||i)
      RETURNING id INTO salary_payment_id;
      INSERT INTO gcmb.financial_transaction(period_id,booking_date,occurred_at,kind,salary_payment_id,reason,created_by,idempotency_key)
      VALUES (period_id,paid_at::date,paid_at,'SALARY',salary_payment_id,tag||' GIẢ LẬP lương',accountant,
        tag||'-FT-SAL-'||salary_payment_id) RETURNING id INTO transaction_id;
      INSERT INTO gcmb.financial_entry(transaction_id,account_id,branch_id,amount_signed)
      VALUES (transaction_id,central_account,branch_id,-salary_amount);
    END LOOP;
    IF m.fixed_other>0 THEN
      INSERT INTO gcmb.expense(branch_id,code,category_id,class_snapshot,kind,payment_source,requested_by,
        recipient_name,reason,amount,approved_amount,recognized_on,approval_threshold_snapshot,status,created_at)
      SELECT branch_id,tag||'-FX-'||m.branch_code||'-'||to_char(m.month,'YYYYMM'),id,'OPEX','PAYMENT','CENTRAL',
        accountant,'Chi phí cố định GIẢ LẬP',tag||' '||m.source_label||' (không gồm lương/cọc)',
        m.fixed_other,m.fixed_other,m.month,3000000,'PAID',paid_at
      FROM gcmb.expense_category WHERE code=tag||'-FIXED' RETURNING id INTO expense_id;
      INSERT INTO gcmb.expense_line(expense_id,description,quantity,unit_price,amount)
      VALUES (expense_id,'Chi phí cố định tổng hợp GIẢ LẬP',1,m.fixed_other,m.fixed_other);
      INSERT INTO gcmb.expense_approval(expense_id,actor_id,role_snapshot,decision,approved_amount,note,created_at)
      VALUES (expense_id,head_office,'HEAD_OFFICE_MANAGER','APPROVE',m.fixed_other,tag||' GIẢ LẬP phê duyệt',paid_at-interval '1 hour');
      INSERT INTO gcmb.expense_payment(expense_id,account_id,amount,status,paid_at,processed_by,idempotency_key)
      VALUES (expense_id,central_account,m.fixed_other,'PAID',paid_at,accountant,tag||'-EP-FX-'||expense_id)
      RETURNING id INTO expense_payment_id;
      INSERT INTO gcmb.financial_transaction(period_id,booking_date,occurred_at,kind,expense_payment_id,reason,created_by,idempotency_key)
      VALUES (period_id,paid_at::date,paid_at,'EXPENSE',expense_payment_id,tag||' GIẢ LẬP chi phí cố định',accountant,
        tag||'-FT-FX-'||expense_payment_id) RETURNING id INTO transaction_id;
      INSERT INTO gcmb.financial_entry(transaction_id,account_id,branch_id,amount_signed)
      VALUES (transaction_id,central_account,branch_id,-m.fixed_other);
    END IF;
  END LOOP;
  FOR d IN SELECT * FROM _seed_day ORDER BY day,branch_code LOOP
    SELECT id INTO branch_id FROM gcmb.branch WHERE code=d.branch_code;
    SELECT id INTO actor_id FROM gcmb.user_account WHERE username=lower(replace(tag,'-','_')||'_'||d.branch_code);
    SELECT id INTO period_id FROM gcmb.financial_period WHERE month=date_trunc('month',d.day)::date;
    SELECT a.id INTO account_id FROM gcmb.financial_account a WHERE a.branch_id=branch_id AND a.kind='CASH_DRAWER' AND a.active LIMIT 1;
    IF d.variable_cost>0 THEN
      paid_at := (d.day+time '18:00') AT TIME ZONE 'Asia/Ho_Chi_Minh';
      INSERT INTO gcmb.expense(branch_id,code,category_id,class_snapshot,kind,payment_source,requested_by,
        recipient_name,reason,amount,approved_amount,recognized_on,approval_threshold_snapshot,status,created_at)
      SELECT branch_id,tag||'-VX-'||d.branch_code||'-'||to_char(d.day,'YYYYMMDD'),id,'OPEX','PAYMENT','CENTRAL',
        accountant,'Chi phí ngày GIẢ LẬP',tag||' '||d.source_label||' (không gồm hoàn cọc)',
        d.variable_cost,d.variable_cost,d.day,3000000,'PAID',paid_at
      FROM gcmb.expense_category WHERE code=tag||'-VARIABLE' RETURNING id INTO expense_id;
      INSERT INTO gcmb.expense_line(expense_id,description,quantity,unit_price,amount)
      VALUES (expense_id,'Chi phí biến đổi tổng hợp GIẢ LẬP',1,d.variable_cost,d.variable_cost);
      INSERT INTO gcmb.expense_approval(expense_id,actor_id,role_snapshot,decision,approved_amount,note,created_at)
      VALUES (expense_id,head_office,'HEAD_OFFICE_MANAGER','APPROVE',d.variable_cost,tag||' GIẢ LẬP phê duyệt',paid_at-interval '1 hour');
      INSERT INTO gcmb.expense_payment(expense_id,account_id,amount,status,paid_at,processed_by,idempotency_key)
      VALUES (expense_id,central_account,d.variable_cost,'PAID',paid_at,accountant,tag||'-EP-VX-'||expense_id)
      RETURNING id INTO expense_payment_id;
      INSERT INTO gcmb.financial_transaction(period_id,booking_date,occurred_at,kind,expense_payment_id,reason,created_by,idempotency_key)
      VALUES (period_id,d.day,paid_at,'EXPENSE',expense_payment_id,tag||' GIẢ LẬP chi phí ngày',accountant,
        tag||'-FT-VX-'||expense_payment_id) RETURNING id INTO transaction_id;
      INSERT INTO gcmb.financial_entry(transaction_id,account_id,branch_id,amount_signed)
      VALUES (transaction_id,central_account,branch_id,-d.variable_cost);
    END IF;
  END LOOP;
  -- BR-03/05: use six available rooms in non-overlapping two-hour slots.
  -- CREATE TABLE AS cannot bind the PL/pgSQL tag variable, so use its literal marker here.
  CREATE TEMP TABLE _seed_booking ON COMMIT DROP AS
  WITH ranked_rooms AS (
    SELECT r.id,r.branch_id,r.room_type_id,
           row_number() OVER (PARTITION BY r.branch_id ORDER BY r.code) AS room_order
    FROM gcmb.room r WHERE r.operating_status='AVAILABLE'
  )
  SELECT gen_random_uuid() AS booking_id,gen_random_uuid() AS allocation_id,
         gen_random_uuid() AS room_charge_id,gen_random_uuid() AS other_charge_id,
         gen_random_uuid() AS bill_id,gen_random_uuid() AS payment_id,
         gen_random_uuid() AS transaction_id,
         seed_day.branch_code,seed_day.day,seed_day.source_label,
         branch_row.id AS branch_id,actor_row.id AS actor_id,period_row.id AS period_id,
         drawer.id AS account_id,room_choice.id AS room_id,price_rule.id AS rule_id,
         price_rule.hourly_price*2 AS room_amount,booking_sequence.booking_index,
         seed_day.revenue/booking_total.booking_count
           + CASE WHEN booking_sequence.booking_index<=seed_day.revenue%booking_total.booking_count THEN 1 ELSE 0 END AS amount,
         slot_time.start_at,slot_time.start_at+interval '2 hours' AS end_at
  FROM _seed_day seed_day
  JOIN gcmb.branch branch_row ON branch_row.code=seed_day.branch_code
  CROSS JOIN LATERAL (SELECT least(12,greatest(1,(seed_day.revenue/300000)::integer)) AS booking_count) booking_total
  CROSS JOIN LATERAL generate_series(1,booking_total.booking_count) AS booking_sequence(booking_index)
  JOIN ranked_rooms room_choice ON room_choice.branch_id=branch_row.id
    AND room_choice.room_order=((booking_sequence.booking_index-1)%6)+1
  JOIN gcmb.room_type room_type_row ON room_type_row.id=room_choice.room_type_id
  LEFT JOIN gcmb.price_rule price_rule ON price_rule.room_type_id=room_choice.room_type_id
    AND price_rule.code='TST-GCMB-EXCEL-2026-PR-'||room_type_row.code
  LEFT JOIN gcmb.user_account actor_row ON actor_row.username='tst_gcmb_excel_2026_'||lower(seed_day.branch_code)
  LEFT JOIN gcmb.financial_period period_row ON period_row.month=date_trunc('month',seed_day.day)::date
  LEFT JOIN LATERAL (
    SELECT a.id FROM gcmb.financial_account a
    WHERE a.branch_id=branch_row.id AND a.kind='CASH_DRAWER' AND a.active LIMIT 1
  ) drawer ON true
  CROSS JOIN LATERAL (
    SELECT (seed_day.day+time '10:00'+((booking_sequence.booking_index-1)/6)*interval '3 hours')
      AT TIME ZONE 'Asia/Ho_Chi_Minh' AS start_at
  ) slot_time
  WHERE seed_day.revenue>0;
  IF (SELECT count(*) FROM _seed_booking) <>
     (SELECT sum(least(12,greatest(1,(revenue/300000)::integer))) FROM _seed_day WHERE revenue>0)
     OR EXISTS (SELECT 1 FROM _seed_booking seed_booking
                WHERE seed_booking.rule_id IS NULL OR seed_booking.actor_id IS NULL
                   OR seed_booking.period_id IS NULL OR seed_booking.account_id IS NULL
                   OR seed_booking.amount<seed_booking.room_amount) THEN
    RAISE EXCEPTION 'Missing room, price, account or period for synthetic bookings';
  END IF;
  RAISE NOTICE 'Prepared % synthetic bookings', (SELECT count(*) FROM _seed_booking);
  INSERT INTO gcmb.booking(id,branch_id,code,contact_name,channel,planned_start,planned_end,actual_checkin,
    actual_checkout,status,refund_cutoff_minutes,created_by,note,created_at,guest_count)
  SELECT seed_booking.booking_id,seed_booking.branch_id,tag||'-BK-'||seed_booking.branch_code||'-'||to_char(seed_booking.day,'YYYYMMDD')||'-'||seed_booking.booking_index,
    'Khách GIẢ LẬP '||seed_booking.booking_index,'WALK_IN',seed_booking.start_at,seed_booking.end_at,seed_booking.start_at,seed_booking.end_at,'COMPLETED',40,seed_booking.actor_id,
    tag||' GIẢ LẬP; '||seed_booking.source_label||'; tổng ngày từ Excel nếu tháng 9',seed_booking.start_at-interval '1 hour',2
  FROM _seed_booking seed_booking;
  INSERT INTO gcmb.room_allocation(id,branch_id,booking_id,room_id,starts_at,ends_at,actual_start,actual_end,
    state,created_by,created_at)
  SELECT seed_booking.allocation_id,seed_booking.branch_id,seed_booking.booking_id,seed_booking.room_id,
    seed_booking.start_at,seed_booking.end_at,seed_booking.start_at,seed_booking.end_at,'FINISHED',
    seed_booking.actor_id,seed_booking.start_at-interval '1 hour'
  FROM _seed_booking seed_booking;
  -- BR-102: each settled bill records its own service value; the remainder is synthetic.
  INSERT INTO gcmb.booking_charge(id,booking_id,allocation_id,price_rule_id,kind,description,quantity,
    unit_price,amount,pricing_snapshot,status,created_at)
  SELECT seed_booking.room_charge_id,seed_booking.booking_id,seed_booking.allocation_id,seed_booking.rule_id,
    'ROOM','Phòng 2 giờ GIẢ LẬP',2,seed_booking.room_amount/2,seed_booking.room_amount,
    jsonb_build_object('marker',tag,'source',seed_booking.source_label),'ACTIVE',seed_booking.start_at
  FROM _seed_booking seed_booking;
  INSERT INTO gcmb.booking_charge(id,booking_id,kind,description,quantity,unit_price,amount,pricing_snapshot,status,created_at)
  SELECT seed_booking.other_charge_id,seed_booking.booking_id,'SERVICE','Doanh thu chưa phân loại GIẢ LẬP',1,
    seed_booking.amount-seed_booking.room_amount,seed_booking.amount-seed_booking.room_amount,
    jsonb_build_object('marker',tag,'source',seed_booking.source_label,'detailUnavailable',true),'ACTIVE',seed_booking.start_at
  FROM _seed_booking seed_booking WHERE seed_booking.amount>seed_booking.room_amount;
  INSERT INTO gcmb.bill(id,booking_id,branch_id,number,status,gross_amount,discount_amount,net_amount,
    issued_at,completed_at,checkout_at,inspection_note,issued_by,created_at)
  SELECT seed_booking.bill_id,seed_booking.booking_id,seed_booking.branch_id,
    tag||'-BL-'||seed_booking.branch_code||'-'||to_char(seed_booking.day,'YYYYMMDD')||'-'||seed_booking.booking_index,
    'SETTLED',seed_booking.amount,0,seed_booking.amount,seed_booking.end_at,seed_booking.end_at,
    seed_booking.end_at,tag||' GIẢ LẬP',seed_booking.actor_id,seed_booking.end_at
  FROM _seed_booking seed_booking;
  INSERT INTO gcmb.bill_line(bill_id,booking_charge_id,description,quantity,unit_price,amount,created_at)
  SELECT seed_booking.bill_id,seed_booking.room_charge_id,'Phòng 2 giờ GIẢ LẬP',2,
    seed_booking.room_amount/2,seed_booking.room_amount,seed_booking.end_at FROM _seed_booking seed_booking;
  INSERT INTO gcmb.bill_line(bill_id,booking_charge_id,description,quantity,unit_price,amount,created_at)
  SELECT seed_booking.bill_id,seed_booking.other_charge_id,'Doanh thu chưa phân loại GIẢ LẬP',1,
    seed_booking.amount-seed_booking.room_amount,seed_booking.amount-seed_booking.room_amount,seed_booking.end_at
  FROM _seed_booking seed_booking WHERE seed_booking.amount>seed_booking.room_amount;
  INSERT INTO gcmb.payment(id,branch_id,booking_id,bill_id,purpose,method,amount,cash_tendered,cash_change,
    received_at,received_by,idempotency_key,created_at)
  SELECT seed_booking.payment_id,seed_booking.branch_id,seed_booking.booking_id,seed_booking.bill_id,
    'BILL','CASH',seed_booking.amount,seed_booking.amount,0,seed_booking.end_at,seed_booking.actor_id,
    tag||'-PAY-'||seed_booking.booking_id,seed_booking.end_at FROM _seed_booking seed_booking;
  INSERT INTO gcmb.financial_transaction(id,period_id,booking_date,occurred_at,kind,payment_id,reason,created_by,idempotency_key)
  SELECT seed_booking.transaction_id,seed_booking.period_id,seed_booking.day,seed_booking.end_at,
    'PAYMENT',seed_booking.payment_id,tag||' GIẢ LẬP thu bill',seed_booking.actor_id,
    tag||'-FT-PAY-'||seed_booking.payment_id FROM _seed_booking seed_booking;
  INSERT INTO gcmb.financial_entry(transaction_id,account_id,branch_id,amount_signed)
  SELECT seed_booking.transaction_id,seed_booking.account_id,seed_booking.branch_id,seed_booking.amount
  FROM _seed_booking seed_booking;
  RAISE NOTICE 'Inserted % synthetic bookings and related records', (SELECT count(*) FROM _seed_booking);
END;
$seed$;
DO $verify$
BEGIN
  IF EXISTS (
    SELECT 1 FROM _seed_month m JOIN gcmb.branch br ON br.code=m.branch_code
    LEFT JOIN LATERAL (
      SELECT sum(b.net_amount) amount FROM gcmb.bill b
      WHERE b.branch_id=br.id AND b.status='SETTLED'
        AND b.completed_at>=(m.month::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh')
        AND b.completed_at<((m.month+interval '1 month') AT TIME ZONE 'Asia/Ho_Chi_Minh')
        AND b.number LIKE 'TST-GCMB-EXCEL-2026%'
    ) revenue ON true
    LEFT JOIN LATERAL (
      SELECT sum(p.amount) amount FROM gcmb.expense e JOIN gcmb.expense_payment p ON p.expense_id=e.id
      WHERE e.branch_id=br.id AND e.code LIKE 'TST-GCMB-EXCEL-2026%' AND p.status='PAID'
        AND p.paid_at>=(m.month::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh')
        AND p.paid_at<((m.month+interval '1 month') AT TIME ZONE 'Asia/Ho_Chi_Minh')
    ) expense ON true
    LEFT JOIN LATERAL (
      SELECT sum(-fe.amount_signed) amount FROM gcmb.financial_transaction ft
      JOIN gcmb.financial_entry fe ON fe.transaction_id=ft.id
      WHERE fe.branch_id=br.id AND ft.kind='SALARY' AND ft.idempotency_key LIKE 'TST-GCMB-EXCEL-2026%'
        AND ft.occurred_at>=(m.month::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh')
        AND ft.occurred_at<((m.month+interval '1 month') AT TIME ZONE 'Asia/Ho_Chi_Minh')
    ) salary ON true
    WHERE COALESCE(revenue.amount,0)<>m.revenue
       OR COALESCE(expense.amount,0)<>m.variable_cost+m.fixed_other
       OR COALESCE(salary.amount,0)<>m.salary
  ) THEN
    RAISE EXCEPTION 'Seed month totals do not match source targets; transaction rolled back';
  END IF;
  IF EXISTS (SELECT 1 FROM gcmb.bill b WHERE b.number LIKE 'TST-GCMB-EXCEL-2026%'
     AND (b.net_amount<>(SELECT COALESCE(sum(l.amount),0) FROM gcmb.bill_line l WHERE l.bill_id=b.id)
       OR b.net_amount<>(SELECT COALESCE(sum(p.amount),0) FROM gcmb.payment p WHERE p.bill_id=b.id))) THEN
    RAISE EXCEPTION 'Bill lines or payment do not balance; transaction rolled back';
  END IF;
  IF EXISTS (SELECT 1 FROM gcmb.room_allocation a
    JOIN gcmb.room_allocation b ON b.room_id=a.room_id AND b.id>a.id
      AND tstzrange(a.starts_at,a.ends_at,'[)') && tstzrange(b.starts_at,b.ends_at,'[)')
    JOIN gcmb.booking k ON k.id=a.booking_id WHERE k.code LIKE 'TST-GCMB-EXCEL-2026%') THEN
    RAISE EXCEPTION 'Room allocation overlap; transaction rolled back';
  END IF;
END;
$verify$;
-- Expected monthly target and source variance. Refunds are a cash outflow, not operating expense.
SELECT m.branch_code,m.month,m.source_label,m.revenue AS target_revenue,
 m.variable_cost+m.salary+m.fixed_other+m.refund_reference AS excel_or_simulated_total_cost,
 m.refund_reference AS refund_excluded_from_operating_profit,
 m.revenue-m.variable_cost-m.salary-m.fixed_other-m.refund_reference AS source_target_profit
FROM _seed_month m ORDER BY m.month,m.branch_code;
-- Reconciliation of records actually read by the monthly performance report.
SELECT m.branch_code,m.month,m.revenue AS target_revenue,COALESCE(b.revenue,0) AS bill_revenue,
 m.variable_cost+m.fixed_other AS target_opex,COALESCE(e.opex,0) AS paid_opex,
 m.salary AS target_salary,COALESCE(s.salary,0) AS ledger_salary,
 m.refund_reference,m.revenue-m.variable_cost-m.fixed_other-m.salary AS target_gcmb_profit,
 COALESCE(b.revenue,0)-COALESCE(e.opex,0)-COALESCE(s.salary,0) AS actual_gcmb_profit
FROM _seed_month m JOIN gcmb.branch br ON br.code=m.branch_code
LEFT JOIN LATERAL (SELECT sum(net_amount) revenue FROM gcmb.bill b WHERE b.branch_id=br.id AND b.status='SETTLED'
 AND (b.completed_at AT TIME ZONE br.timezone)::date>=m.month
 AND (b.completed_at AT TIME ZONE br.timezone)::date<(m.month+interval '1 month')::date
 AND b.number LIKE 'TST-GCMB-EXCEL-2026%') b ON true
LEFT JOIN LATERAL (SELECT sum(ep.amount) opex FROM gcmb.expense x JOIN gcmb.expense_payment ep ON ep.expense_id=x.id
 WHERE x.branch_id=br.id AND ep.status='PAID' AND x.class_snapshot='OPEX'
 AND (ep.paid_at AT TIME ZONE br.timezone)::date>=m.month
 AND (ep.paid_at AT TIME ZONE br.timezone)::date<(m.month+interval '1 month')::date
 AND x.code LIKE 'TST-GCMB-EXCEL-2026%') e ON true
LEFT JOIN LATERAL (SELECT sum(-fe.amount_signed) salary FROM gcmb.financial_transaction ft
 JOIN gcmb.financial_entry fe ON fe.transaction_id=ft.id WHERE fe.branch_id=br.id AND ft.kind='SALARY'
 AND (ft.occurred_at AT TIME ZONE br.timezone)::date>=m.month
 AND (ft.occurred_at AT TIME ZONE br.timezone)::date<(m.month+interval '1 month')::date
 AND ft.idempotency_key LIKE 'TST-GCMB-EXCEL-2026%') s ON true
ORDER BY m.month,m.branch_code;
SELECT 'bill_line_mismatch' check_name,count(*) FROM gcmb.bill b WHERE b.number LIKE 'TST-GCMB-EXCEL-2026%'
 AND b.net_amount<>(SELECT COALESCE(sum(l.amount),0) FROM gcmb.bill_line l WHERE l.bill_id=b.id)
UNION ALL SELECT 'bill_payment_mismatch',count(*) FROM gcmb.bill b WHERE b.number LIKE 'TST-GCMB-EXCEL-2026%'
 AND b.net_amount<>(SELECT COALESCE(sum(p.amount),0) FROM gcmb.payment p WHERE p.bill_id=b.id)
UNION ALL SELECT 'overlapping_test_allocations',count(*) FROM gcmb.room_allocation a
 JOIN gcmb.room_allocation b ON b.room_id=a.room_id AND b.id>a.id AND tstzrange(a.starts_at,a.ends_at,'[)') && tstzrange(b.starts_at,b.ends_at,'[)')
 JOIN gcmb.booking k ON k.id=a.booking_id WHERE k.code LIKE 'TST-GCMB-EXCEL-2026%'
UNION ALL SELECT 'old_test_bookings_remaining',count(*) FROM gcmb.booking WHERE code LIKE 'TST-GCMB-20261114%';
COMMIT;
